levels.example:
# 待办事项管理器
todos = []
while True:
    print("1. 添加 2. 查看 3. 退出")
    choice = input("请选择：")
    if choice == "1":
        todo = input("输入待办：")
        todos.append(todo)
    elif choice == "2":
        for i, todo in enumerate(todos):
            print(f"{i+1}. {todo}")
    elif choice == "3":
        break

guidedHints.code:
# 第二步：添加和查看
todos = []
while True:
    print("1. 添加 2. 查看 3. 删除 4. 退出")
    choice = input("请选择：")
    if choice == "1":
        todo = input("输入待办：")
        todos.append(todo)
    elif choice == "2":
        for i, todo in enumerate(todos):
            print(f"{i+1}. {todo}")

# 第三步：完整答案
todos = []
while True:
    print("1. 添加 2. 查看 3. 删除 4. 退出")
    choice = input("请选择：")
    if choice == "1":
        todo = input("输入待办：")
        todos.append(todo)
    elif choice == "2":
        for i, todo in enumerate(todos):
            print(f"{i+1}. {todo}")
    elif choice == "3":
        index = int(input("删除第几个：")) - 1
        if 0 <= index < len(todos):
            todos.pop(index)
    elif choice == "4":
        break

